/* Shared prototype state, primitives, and discovery. No production API calls. */
'use strict';
const AC = window.AC = {};
AC.esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
AC.params = new URLSearchParams(location.search);
AC.base = document.body.dataset.root || '';
AC.url = (page='index',query='') => AC.base+(page==='index'?'index.html':'screens/'+page+'.html')+query;
AC.link = (p,label,cls='btn',q='')=>`<a class="${cls}" href="${AC.url(p,q)}">${label}</a>`;
AC.icons = {search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5"/>',trip:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M8 7v14m8-14v14"/>',chart:'<path d="M4 3v17h17M8 16v-5m5 5V7m5 9V4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',save:'<path d="M6 3h12v18l-6-4-6 4z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',intro:'<circle cx="5" cy="12" r="3"/><circle cx="19" cy="6" r="3"/><circle cx="19" cy="18" r="3"/><path d="m8 11 8-4m-8 6 8 4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M7 14h3m4 0h3m-10 3h3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',admin:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',file:'<path d="M14 2H5v20h14V7Zm0 0v5h5M8 12h8m-8 4h8"/>',plus:'<path d="M12 4v16M4 12h16"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>'};
AC.icon=(n)=>`<svg class="od-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${AC.icons[n]||AC.icons.info}</svg>`;
AC.read=()=>{try{return JSON.parse(localStorage.getItem('alumni-connect-prototype')||'null')||{}}catch{return {}}};
AC.state=Object.assign({saved:['p2','p5'],notes:{},lists:['Chicago relationships','Potential mentors'],interactions:[],followups:[],introStage:'none',rsvps:[],audit:[],removed:[],profile:{name:'Alex Morgan',title:'Director, Strategic Partnerships',company:'Northfield Advisory',city:'Chicago, IL',year:'2008'},privacy:{email:'members',phone:'connections',website:'members',linkedin:'members'},theme:'system'},AC.read());
AC.persist=()=>{try{localStorage.setItem('alumni-connect-prototype',JSON.stringify(AC.state))}catch{}};
if(AC.state.theme!=='system') document.documentElement.dataset.theme=AC.state.theme;
