AC.byId=id=>AC.people.find(p=>p.id===id)||AC.people[0];
AC.visiblePeople=()=>AC.people.filter(p=>!AC.state.removed.includes(p.id));
AC.badge=p=>p.confirmed?`<span class="chip success">${AC.icon('check')}Confirmed</span>`:`<span class="chip subtle">Unconfirmed</span>`;
AC.avatar=(p,extra='')=>`<span class="avatar ${p.confirmed?'red':''} ${extra}" aria-hidden="true">${p.initials}</span>`;
AC.btn=(text,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
AC.brand=()=>`<a class="brand" href="${AC.url()}"><span class="brand-symbol" aria-hidden="true">a<span style="color:var(--fg);font-size:20px">·</span></span><span><span class="brand-name">Alumni Connect</span><span class="brand-sub">Wisconsin · Nationwide</span></span></a>`;
AC.nav=[['index','Discover','search'],['relationships','Relationships','people'],['trips','Trips','trip'],['insights','Insights','chart']];
AC.adminNav=[['admin-import','Roster import','file'],['admin-review','Profile review','people'],['admin-verification','Verification','admin'],['admin-removal','Removal requests','lock'],['admin-audit','Audit log','clock']];
AC.screen=document.body.dataset.screen||'index';
AC.group=()=>AC.screen.startsWith('admin-')?'admin':(['profile','search','recommendations'].includes(AC.screen)?'index':(['saved','introductions','introduction-review','introduction-response','followups','lists'].includes(AC.screen)?'relationships':(['trip-planner','trip-shortlist','outreach','meeting'].includes(AC.screen)?'trips':AC.screen)));
AC.title=(title,desc='',action='',eyebrow='Your alumni network, nationwide.')=>`<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;
AC.notice=(text,type='')=>`<div class="notice ${type}" role="${type==='error'?'alert':'status'}">${AC.icon(type==='success'?'check':'info')}<div>${text}</div></div>`;
AC.empty=(title,text,action='')=>`<div class="empty">${AC.icon('search')}<h2>${title}</h2><p>${text}</p>${action}</div>`;
AC.options=(list,value)=>list.map(v=>`<option ${v===value?'selected':''} value="${AC.esc(v)}">${AC.esc(v)}</option>`).join('');
AC.field=(label,id,value='',type='text',help='',attrs='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${AC.esc(value)}" ${attrs}>${help?`<small>${help}</small>`:''}<span class="error-text" id="${id}-error" hidden></span></div>`;
AC.select=(label,id,values,value='',help='')=>`<div class="field"><label for="${id}">${label}</label><select id="${id}">${AC.options(values,value)}</select>${help?`<small>${help}</small>`:''}</div>`;
AC.textarea=(label,id,value='',help='')=>`<div class="field"><label for="${id}">${label}</label><textarea id="${id}">${AC.esc(value)}</textarea>${help?`<small>${help}</small>`:''}</div>`;
AC.skeleton=()=>`<div role="status" aria-label="Loading alumni">${[1,2,3].map(()=>'<div class="loading-row"><div class="skeleton big"></div><div class="skeleton"></div><div class="skeleton short"></div></div>').join('')}<p class="pad muted small">Finding relevant alumni…</p></div>`;
AC.stateBlock=(normal,emptyTitle='Nothing here yet',emptyText='Try broadening your search.',action='')=>{let s=AC.params.get('state');return s==='loading'?AC.skeleton():s==='error'?`<div class="pad">${AC.notice('We couldn’t load this information. Your changes have been kept.','error')}<div class="form-actions">${AC.btn('Try again','retry','primary')}</div></div>`:s==='empty'?AC.empty(emptyTitle,emptyText,action):normal};
AC.person=(p,reason=true)=>`<article class="person">${AC.avatar(p)}<div><div class="person-name"><a href="${AC.url('profile','?id='+p.id)}">${AC.esc(p.name)}</a>${AC.badge(p)}</div><p class="person-sub">${AC.esc(p.title)} · ${AC.esc(p.company)}</p><div class="person-meta"><span>${AC.icon('pin')} ${p.metro}</span><span>${p.degree} ’${String(p.year).slice(-2)}</span></div>${reason?`<div class="person-why">${AC.icon('intro')}<span>${AC.esc(p.relation)}</span></div>`:''}<div class="person-tags">${p.open.slice(0,2).map(t=>`<span class="chip">${t}</span>`).join('')}${!p.confirmed?'<span class="meta">Profile not yet claimed · Public / licensed sources</span>':''}</div></div><div class="person-actions">${AC.btn(AC.icon(AC.state.saved.includes(p.id)?'check':'save'), 'save','icon-button',`data-id="${p.id}" aria-label="${AC.state.saved.includes(p.id)?'Unsave':'Save'} ${AC.esc(p.name)}" aria-pressed="${AC.state.saved.includes(p.id)}"`)}${AC.link('profile','View profile','btn','?id='+p.id)}</div></article>`;
AC.personList=people=>people.map(p=>AC.person(p)).join('');
AC.relationshipTabs=()=>`<div class="tabs">${[['relationships','Overview'],['saved','Saved contacts'],['lists','Lists'],['introductions','Introductions'],['followups','Follow-ups']].map(([p,t])=>`<a href="${AC.url(p)}" ${AC.screen===p?'aria-current="page"':''}>${t}</a>`).join('')}</div>`;
AC.shell=(html)=>{const admin=AC.group()==='admin';let nav=admin?AC.adminNav:AC.nav;return `<a class="skip" href="#main">Skip to content</a><div class="app" id="app-shell"><aside class="sidebar">${AC.brand()}<nav aria-label="${admin?'Administration':'Main navigation'}">${nav.map(([p,t,i])=>`<a class="nav-item" href="${AC.url(p)}" ${AC.group()===p||AC.screen===p?'aria-current="page"':''}>${AC.icon(i)}<span>${t}</span>${p==='relationships'?`<span class="nav-count">${AC.state.saved.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom">${admin?AC.link('index','← Member workspace','btn quiet'):`<div class="chapter-note"><span class="eyebrow">A shared beginning.</span><p>A nationwide network of Wisconsin alumni, built on real relationships.</p>${AC.link('recommendations','Find your next connection '+AC.icon('arrow'),'small')}</div>`}<div><a class="nav-item" href="${AC.url('settings')}">${AC.icon('settings')}<span>Profile & privacy</span></a><a class="nav-item" href="${AC.url(admin?'catalog':'admin-review')}">${AC.icon(admin?'file':'admin')}<span>${admin?'Prototype directory':'Administration'}</span></a></div><div class="account"><span class="avatar small red">AM</span><a href="${AC.url('edit-profile')}" class="od-field"><strong class="small">${AC.esc(AC.state.profile.name)}</strong><span class="meta">Class of ${AC.state.profile.year} · Confirmed</span></a></div></div></aside><div class="workspace"><header class="topbar"><span class="crumb">Your network <span style="padding:0 8px">/</span> <b>${admin?'Administration':(AC.nav.find(n=>n[0]===AC.group())||['',AC.screen.split('-').join(' ')])[1]}</b></span><a class="mobile-brand" href="${AC.url()}">Alumni Connect<span class="accent">.</span></a><div class="top-actions"><span class="trust">${AC.icon('lock')}<span>Private. Verified alumni only.</span></span><button class="icon-button" data-action="theme" aria-label="Switch light and dark theme">${AC.icon('sun')}</button><button class="icon-button menu-button" data-action="menu" aria-label="Open navigation" aria-expanded="false">${AC.icon('menu')}</button></div></header><main class="content" id="main" tabindex="-1">${html}</main></div></div>`};
AC.toast=(message)=>{let n=document.getElementById('toast');n.textContent=message;n.hidden=false;clearTimeout(AC.toastTimer);AC.toastTimer=setTimeout(()=>n.hidden=true,4500)};
AC.modal=(title,body,trigger)=>{const d=document.getElementById('dialog');AC.modalTrigger=trigger||document.activeElement;d.innerHTML=`<button class="icon-button close" data-action="close-dialog" aria-label="Close dialog">${AC.icon('close')}</button><h2 id="dialog-title">${title}</h2>${body}`;d.showModal();};
AC.close=()=>{document.getElementById('dialog').close();if(AC.modalTrigger?.isConnected)AC.modalTrigger.focus()};
AC.renders={};AC.handlers={};
AC.renders.index=()=>`${AC.title('Good connections start here.','Find the people, shared experiences, and warm introductions that move you forward.',AC.link('trip-planner',AC.icon('plus')+' Plan a trip','btn'),'A Wisconsin beginning. A nationwide network.')}<div class="split"><div class="stack"><section aria-labelledby="search-label"><label class="search-label" id="search-label" for="discovery-search">Who would you like to connect with?</label><div class="search-box">${AC.icon('search')}<input id="discovery-search" placeholder="Try “commercial real estate in Chicago”" autocomplete="off">${AC.btn('Find alumni '+AC.icon('arrow'),'home-search','primary')}</div><div class="search-hints"><span>Try a search:</span>${['Finance in New York','Tech mentors class of 2010','Banking in Dallas'].map(q=>`<button data-action="suggest-search" data-query="${q}">${q}</button>`).join('')}</div></section><section class="panel"><div class="pad" style="padding-bottom:0"><div class="section-head"><div><h2>People worth knowing</h2><p class="small muted">A few starting points, based on your professional goal.</p></div>${AC.link('recommendations','See all '+AC.icon('arrow'),'btn quiet')}</div><div class="od-cluster small muted" style="padding-bottom:20px"><span class="chip ai">AI-assisted suggestions</span><span>Goal: build partnerships in Chicago</span></div></div><div id="discovery-people">${AC.stateBlock(AC.personList(AC.visiblePeople().filter(p=>['p1','p2','p9'].includes(p.id))))}</div></section><div class="notice">${AC.icon('lock')}<div><strong>Your network. Your boundaries.</strong><p class="small muted">Contact details follow each member’s privacy settings. Introductions always ask both sides first.</p>${AC.link('settings','Review your privacy','btn quiet')}</div></div></div><aside class="right-rail stack"><section class="trip-callout"><div class="network-graphic" aria-hidden="true"><span class="avatar small">AM</span><span class="network-line"></span><span class="avatar">EB</span><span class="network-line"></span><span class="avatar small">RF</span></div><div class="eyebrow">Make the most of your next trip</div><h2>A new city.<br>A familiar connection.</h2><p>Turn a few days away into a few meaningful conversations.</p>${AC.link('trip-planner','Find alumni to meet '+AC.icon('arrow'),'btn primary')}</section><section class="panel pad"><h2 class="rail-title">Keep the conversation going</h2><div class="rail-list"><a class="rail-link" href="${AC.url('saved')}">${AC.icon('save')}<div><strong class="small">${AC.state.saved.length} saved contacts</strong><p>Pick up where you left off.</p></div></a><a class="rail-link" href="${AC.url('introductions')}">${AC.icon('intro')}<div><strong class="small">A warmer way in</strong><p>Ask someone you know to introduce you.</p></div></a><a class="rail-link" href="${AC.url('insights')}">${AC.icon('chart')}<div><strong class="small">Explore the network</strong><p>See alumni by market and industry.</p></div></a></div></section><p class="footnote">Prototype workspace · Fictional members and sample data. No messages are sent.</p></aside></div>`;
AC.renders.search=()=>{let q=AC.params.get('q')||AC.state.searchQuery||'';return `${AC.title('Find your people.','Search by what you need. Refine by who, where, and how you’d like to connect.','','Discover / Search')}<label class="search-label" for="query">Search the alumni network</label><div class="search-box">${AC.icon('search')}<input id="query" value="${AC.esc(q)}" placeholder="Industry, city, name, class year, or goal">${AC.btn('Search alumni','run-search','primary')}</div><div class="filter-row"><label class="sr-only" for="industry">Industry</label><select id="industry">${AC.options(['All industries',...AC.sectors])}</select><label class="sr-only" for="metro">City</label><select id="metro">${AC.options(['All cities','Chicago','Dallas','Austin','New York'])}</select><label class="sr-only" for="radius">Radius</label><select id="radius">${AC.options(['25 miles','50 miles','100 miles','Nationwide'])}</select><label class="sr-only" for="specialty">Specialty</label><select id="specialty">${AC.options(['All specialties',...AC.specialties])}</select><label class="sr-only" for="class-year">Class year</label><input id="class-year" type="number" min="1940" max="2030" placeholder="Class year" aria-label="Class year" style="width:128px"><label class="sr-only" for="open-to">Open to</label><select id="open-to">${AC.options(['Any openness',...AC.openTags])}</select><label class="checkbox"><input id="confirmed-only" type="checkbox">Confirmed only</label>${AC.btn('Clear filters','clear-search','quiet')}</div><p class="meta" id="parsed-query" style="margin:16px 0"></p><div class="split"><section class="panel"><div class="section-head pad" style="margin:0"><h2 id="result-count">Alumni</h2><label class="small muted">Sort <select id="result-sort" style="width:auto;font-size:12px"><option>Relevance</option><option>Name</option><option>Class year</option></select></label></div><div id="search-results"></div></section><aside class="stack right-rail"><section class="panel pad"><h2>Search breakdown</h2><div id="search-breakdown"></div></section><section class="panel pad"><h3>What does unconfirmed mean?</h3><p class="small muted" style="margin-top:12px">A profile assembled from public or licensed sources, before the alumnus has joined. It has not yet been claimed or checked by that person.</p><p class="small muted" style="margin-top:12px">Confirmed means the person has claimed and verified their profile. It does not imply university endorsement.</p></section></aside></div>`};
AC.sectors=['Agriculture','Arts & entertainment','Construction','Education','Energy','Finance','Government','Healthcare','Hospitality','Legal','Manufacturing','Nonprofit','Professional services','Real estate','Retail','Technology','Transportation'];
AC.specialties=['Agribusiness','Crop science','Food systems','Forestry','Performing arts','Design','Media','Film & television','General contracting','Civil construction','Building services','Higher education','K–12 education','Education technology','Oil & gas','Renewable energy','Utilities','Investment banking','Commercial banking','Private equity','Wealth management','Insurance','Asset management','Public administration','Policy','Public safety','Clinical practice','Health technology','Hospital administration','Biotechnology','Public health','Hotels','Restaurants','Travel services','Corporate law','Legal services','Litigation','Intellectual property','Industrial manufacturing','Consumer products','Aerospace','Automotive','Community development','Philanthropy','Advocacy','Consulting','Accounting','Marketing','Human resources','Architecture','Commercial real estate','Residential real estate','Property management','Real estate development','E-commerce','Store operations','Merchandising','Software','Hardware','Cybersecurity','Data & AI','Telecommunications','Logistics','Aviation','Rail & transit','Shipping'];
AC.openTags=['Networking','Mentoring','Hiring','Job seeking','Investing','Fundraising','Referrals','Meeting travelers','Speaking'];
AC.searchPage=0;
AC.search=()=>{const q=document.getElementById('query');if(!q)return;const text=q.value.toLowerCase().trim();const city=document.getElementById('metro').value,ind=document.getElementById('industry').value,yr=document.getElementById('class-year').value,sp=document.getElementById('specialty').value,op=document.getElementById('open-to').value,cf=document.getElementById('confirmed-only').checked;let parsed=[];let inferredCity=['chicago','dallas','austin','new york'].find(c=>text.includes(c));let inferredInd=text.includes('tech')?'Technology':text.includes('real estate')?'Real estate':text.includes('bank')||text.includes('finance')?'Finance':null;let inferredYear=text.match(/\b(19\d{2}|20\d{2})\b/)?.[0];if(inferredCity)parsed.push('City: '+inferredCity);if(inferredInd)parsed.push('Industry: '+inferredInd);if(inferredYear)parsed.push('Class: '+inferredYear);if(text.includes('mentor'))parsed.push('Open to: Mentoring');let people=AC.visiblePeople().filter(p=>{let hay=(p.name+' '+p.title+' '+p.company+' '+p.industry+' '+p.specialty+' '+p.city+' '+p.year+' '+p.open.join(' ')).toLowerCase();let natural=text.replace(/commercial real estate|real estate|new york|class of|\b(in|near|and|alumni|of|the|tech|technology|finance|banking|mentors?|19\d{2}|20\d{2}|chicago|dallas|austin)\b/g,' ').replace(/\s+/g,' ').trim();return (!natural||natural.split(' ').every(w=>hay.includes(w)))&&(!inferredCity||p.city.toLowerCase()===inferredCity)&&(!inferredInd||p.industry===inferredInd)&&(!inferredYear||p.year==inferredYear)&&(!text.includes('mentor')||p.open.includes('Mentoring'))&&(city==='All cities'||p.city===city)&&(ind==='All industries'||p.industry===ind)&&(!yr||p.year==yr)&&(sp==='All specialties'||p.specialty===sp)&&(op==='Any openness'||p.open.includes(op))&&(!cf||p.confirmed)});let sort=document.getElementById('result-sort').value;if(sort==='Name')people.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='Class year')people.sort((a,b)=>b.year-a.year);let confirmed=people.filter(p=>p.confirmed).length;document.getElementById('result-count').textContent=`${people.length} alumni`;document.getElementById('parsed-query').textContent=(parsed.length?'Interpreted filters · '+parsed.join(' · ')+' · ':'')+'Sample dataset · Radius applies to metro centers in this prototype';let content=people.length?AC.personList(people.slice(AC.searchPage*5,AC.searchPage*5+5))+`<div class="pagination"><span>${confirmed} confirmed · ${people.length-confirmed} unconfirmed records</span><div class="od-cluster">${AC.btn('Previous','previous-page','',AC.searchPage===0?'disabled':'')}<span>Page ${AC.searchPage+1} of ${Math.ceil(people.length/5)}</span>${AC.btn('Next','next-page','',(AC.searchPage+1)*5>=people.length?'disabled':'')}</div></div>`:AC.empty('No matches yet','Try a wider market, remove a filter, or search for a different specialty.',AC.btn('Clear filters','clear-search','primary'));document.getElementById('search-results').innerHTML=AC.stateBlock(content,'No matches yet','Try widening your search.',AC.btn('Clear filters','clear-search','primary'));let breakdown=(key,title)=>`<h3 class="small" style="margin-top:24px">${title}</h3>${[...new Set(people.map(p=>p[key]))].map(v=>{let ps=people.filter(p=>p[key]===v);return `<div class="detail-row"><strong class="small">${v}</strong><span class="meta">${ps.filter(p=>p.confirmed).length} confirmed · ${ps.filter(p=>!p.confirmed).length} unconfirmed</span></div>`}).join('')||'<p class="small muted">No matching records</p>'}`;document.getElementById('search-breakdown').innerHTML=breakdown('industry','By industry')+breakdown('city','By metro');AC.state.searchQuery=q.value;AC.params.set('q',q.value);AC.persist()};
AC.handlers['home-search']=()=>{const q=document.getElementById('discovery-search').value;AC.go('search','?q='+encodeURIComponent(q))};
AC.handlers['suggest-search']=b=>AC.go('search','?q='+encodeURIComponent(b.dataset.query));
AC.handlers['run-search']=()=>{AC.searchPage=0;AC.search()};
AC.handlers['clear-search']=()=>{['query','class-year'].forEach(id=>document.getElementById(id).value='');['industry','metro','specialty','open-to','radius'].forEach(id=>document.getElementById(id).selectedIndex=0);document.getElementById('confirmed-only').checked=false;AC.params.delete('state');AC.searchPage=0;AC.search()};
AC.handlers['next-page']=()=>{AC.searchPage++;AC.search();document.getElementById('result-count').tabIndex=-1;document.getElementById('result-count').focus()};
AC.handlers['previous-page']=()=>{AC.searchPage=Math.max(0,AC.searchPage-1);AC.search();document.getElementById('result-count').tabIndex=-1;document.getElementById('result-count').focus()};
AC.go=(p,q='')=>{location.href=AC.url(p,q)};
AC.handlers.save=b=>{let id=b.dataset.id;let saved=AC.state.saved.includes(id);AC.state.saved=saved?AC.state.saved.filter(i=>i!==id):[...AC.state.saved,id];AC.persist();document.querySelectorAll(`[data-action="save"][data-id="${id}"]`).forEach(el=>{el.innerHTML=AC.icon(saved?'save':'check')+(el.dataset.text?' '+(saved?'Save contact':'Saved'):'');el.setAttribute('aria-pressed',String(!saved));el.setAttribute('aria-label',(saved?'Save ':'Unsave ')+AC.byId(id).name)});AC.toast(saved?'Contact removed from saved contacts':'Contact saved to your relationships');if(AC.screen==='saved')AC.render()};
AC.handlers.theme=()=>{let dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches);AC.state.theme=dark?'light':'dark';document.documentElement.dataset.theme=AC.state.theme;AC.persist();AC.toast(`${AC.state.theme==='dark'?'Dark':'Light'} theme enabled`)};
AC.handlers.menu=b=>{let app=document.getElementById('app-shell');let open=app.classList.toggle('menu-open');b.setAttribute('aria-expanded',String(open));if(open){let nav=document.querySelector('.sidebar .nav-item');nav.focus();nav.scrollTop=0}};
AC.handlers['close-dialog']=AC.close;
AC.handlers.retry=()=>{AC.params.delete('state');AC.render();AC.toast('Information loaded from the sample dataset')};
AC.addAudit=(action)=>{AC.state.audit.unshift({action,at:new Date().toLocaleString(),actor:'Alex Morgan'});AC.persist()};
AC.render=()=>{let fn=AC.renders[AC.screen]||AC.renders.index;const html=fn();document.getElementById('root').innerHTML=['sign-in','verification-pending','claim','remove'].includes(AC.screen)?html:AC.shell(html);if(AC.screen==='search')AC.search();AC.afterRender?.()};
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let fn=AC.handlers[b.dataset.action];if(fn)fn(b,e)});
document.addEventListener('change',e=>{if(AC.screen==='search'&&e.target.matches('select,input[type=checkbox],#class-year')){AC.searchPage=0;AC.search()}AC.onChange?.(e)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='discovery-search'){e.preventDefault();AC.handlers['home-search']()}if(e.key==='Enter'&&e.target.id==='query'){e.preventDefault();AC.handlers['run-search']()}if(e.key==='Escape'&&document.getElementById('app-shell')?.classList.contains('menu-open')){document.getElementById('app-shell').classList.remove('menu-open');document.querySelector('[data-action=menu]').focus()}AC.onKey?.(e)});
document.addEventListener('DOMContentLoaded',()=>{document.getElementById('dialog').addEventListener('close',()=>{if(AC.modalTrigger?.isConnected)AC.modalTrigger.focus()});AC.render()});
